void rotate(const int16_t* in, int16_t* out, size_t n,
            float c, float s) {
  for (size_t k = 0; k < n; ++k) {
    float re = in[2*k] * c - in[2*k+1] * s;
    float im = in[2*k] * s + in[2*k+1] * c;
    out[2*k]   = static_cast<int16_t>(re);
    out[2*k+1] = static_cast<int16_t>(im);
  }
}

using cf = std::complex<float>;
void mix(const cf* in, cf* out, size_t n,
         float& phase, float dphi) {
  for (size_t k = 0; k < n; ++k) {
    out[k] = in[k] * std::polar(1.0f, phase);
    phase += dphi;
  }
}

