int16_t sat16(float x) {
  if (!(x == x)) return 0;               // NaN
  if (x >= 32767.0f) return 32767;
  if (x <= -32768.0f) return -32768;
  return static_cast<int16_t>(std::lrintf(x));
}

class Nco {
  std::complex<double> p_{1.0, 0.0}, w_;
public:
  Nco(double f, double fs)
    : w_(std::polar(1.0, 2.0 * std::numbers::pi * f / fs)) {}
  void mix(const int16_t* in, int16_t* out, size_t n) {
    const float g = 0.70710678f;          // -3 dB backoff
    for (size_t k = 0; k < n; ++k) {
      std::complex<float> x(in[2*k] * g, in[2*k+1] * g);
      std::complex<float> y = x * std::complex<float>(p_);
      out[2*k] = sat16(y.real());
      out[2*k+1] = sat16(y.imag());
      p_ *= w_;
    }
    p_ /= std::abs(p_);                   // renormalize
  }
};
