// dphi (rad/sample) for freq f Hz at sample rate fs Hz
float nco_dphi(int f, int fs) {
    return 2.0f * 3.14159265f * (f / fs);
}

using cf = std::complex<float>;
// called once per chunk; phase must continue across chunks
void mix(const cf* in, cf* out, size_t n, float dphi) {
    float phase = 0.0f;
    for (size_t k = 0; k < n; ++k) {
        out[k] = in[k] * std::polar(1.0f, phase);
        phase += dphi;
    }
}

int16_t sat16(float x) {
    int16_t v = static_cast<int16_t>(x);
    if (v > 32767) v = 32767;
    if (v < -32768) v = -32768;
    return v;
}
